using Hexalith.FrontComposer.SourceTools.Transforms;
int tested = 0;
for (int value = char.MinValue; value <= char.MaxValue; value++)
{
    string input = ((char)value).ToString();
    string actual = CamelCaseHumanizer.Humanize(input)!;
    if (string.IsNullOrWhiteSpace(actual) != string.IsNullOrWhiteSpace(input)) throw new Exception($"Whitespace classification changed at {value}");
    if (string.IsNullOrWhiteSpace(actual) && actual != input) throw new Exception($"Whitespace text changed at {value}");
    if (string.IsNullOrEmpty(actual)) throw new Exception($"Nonempty input removed at {value}");
    tested++;
}
if (CamelCaseHumanizer.Humanize(null) is not null || CamelCaseHumanizer.Humanize("") != "") throw new Exception("Null/empty contract changed");
Console.WriteLine(System.Text.Json.JsonSerializer.Serialize(new {status="passed",utf16Characters=tested,nullAndEmpty=true}));
